package com.reverseit.cancore

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Parity test against cantools.
 *
 * Cases are pre-generated by `tools/dbc_parity_generate.py` and shipped as
 * a TSV in `src/test/resources/dbc_parity_cases.tsv`. The Vtrux DBC files
 * are copied alongside in `src/test/resources/dbcs/`. For each line in the
 * TSV the test parses the named DBC, decodes the hex payload, and asserts
 * every expected signal matches within `TOLERANCE`. Signals decoded by
 * cantools but absent from the Kotlin result (or vice versa) are reported
 * as parity failures.
 *
 * Regenerate after changing a Vtrux DBC:
 *     py -3.12 tools/dbc_parity_generate.py
 */
class DbcParityTest {

    private val tolerance = 1e-6

    @Test
    fun parityWithCantools() {
        val tsv = readResource("/dbc_parity_cases.tsv")
        val dbcCache = HashMap<String, Dbc>()
        var totalCases = 0
        val failures = mutableListOf<String>()

        for (rawLine in tsv.lineSequence()) {
            val line = rawLine.trimEnd('\r', '\n')
            if (line.isEmpty() || line.startsWith("#")) continue
            val cols = line.split('\t')
            require(cols.size in 3..4) { "malformed parity TSV line: $line" }
            val dbcName = cols[0]
            val msgId = cols[1].toInt()
            val payload = hexToBytes(cols[2])
            val expected = if (cols.size == 4) parseExpected(cols[3]) else emptyMap()

            val dbc = dbcCache.getOrPut(dbcName) {
                DbcParser.parse(readResource("/dbcs/$dbcName"))
            }
            val message = dbc.messages[msgId]
            if (message == null) {
                failures += "[$dbcName 0x${msgId.toString(16)}] message not in parsed DBC"
                continue
            }
            val actual = try {
                DbcDecoder.decode(message, padTo(payload, message.length))
            } catch (e: Exception) {
                failures += "[$dbcName ${message.name}] decode threw: ${e.message}"
                continue
            }

            totalCases++
            for ((name, expVal) in expected) {
                val gotVal = actual[name]
                if (gotVal == null) {
                    failures += "[$dbcName ${message.name}] signal $name missing in Kotlin output"
                    continue
                }
                if (!approxEqual(gotVal, expVal)) {
                    failures += "[$dbcName ${message.name}] $name: expected=$expVal kotlin=$gotVal payload=${cols[2]}"
                }
            }
            for (name in actual.keys) {
                if (name !in expected) {
                    failures += "[$dbcName ${message.name}] signal $name unexpected (not in cantools output) payload=${cols[2]}"
                }
            }
        }

        assertTrue(
            "parity failures:\n" +
                failures.take(50).joinToString("\n") +
                if (failures.size > 50) "\n... (${failures.size - 50} more)" else "",
            failures.isEmpty()
        )
        assertTrue("expected at least 100 parity cases, got $totalCases", totalCases >= 100)
    }

    @Test
    fun parsesAllVtruxDbcsWithoutError() {
        val names = listOf(
            "epri-pt-bus.dbc",
            "epri-obd-bus.dbc",
            "BelInverter-v2.dbc",
            "GMW8762_PPEI_GMLAN.dbc",
        )
        for (name in names) {
            val text = readResource("/dbcs/$name")
            val dbc = DbcParser.parse(text)
            assertFalse("$name parsed 0 messages", dbc.messages.isEmpty())
        }
    }

    @Test
    fun multiplexedDecodeReturnsOnlyActiveGroup() {
        val dbc = DbcParser.parse(readResource("/dbcs/BelInverter-v2.dbc"))
        val msg = dbc.messages[0x18FFD4C0]
        assertNotNull("BINV_status (0x18FFD4C0) missing from BelInverter-v2.dbc", msg)
        msg!!

        // Build a payload whose mux nibble (low 8 bits of byte 0) is each
        // valid value in turn; assert only that mux group's signals appear.
        val payload = ByteArray(8) { 0 }
        for (muxVal in 0..3) {
            payload[0] = muxVal.toByte()
            val decoded = DbcDecoder.decode(msg, payload)
            val muxOut = decoded["BELINV_statusMultiplexer"]
                ?: throw AssertionError("multiplexer missing from decoded output")
            assertEquals(muxVal.toDouble(), muxOut, 0.0)
            // No signal from a *different* mux group should be present.
            for (sig in msg.signals) {
                val role = sig.mux
                if (role is MuxRole.Group && role.value != muxVal) {
                    assertFalse(
                        "signal ${sig.name} (mux ${role.value}) leaked into mux=$muxVal decode",
                        decoded.containsKey(sig.name),
                    )
                }
            }
        }
    }

    // -- helpers -----------------------------------------------------------

    private fun readResource(path: String): String {
        val stream = javaClass.getResourceAsStream(path)
            ?: throw IllegalStateException("missing test resource: $path")
        return stream.bufferedReader(Charsets.UTF_8).use { it.readText() }
    }

    private fun hexToBytes(s: String): ByteArray {
        require(s.length % 2 == 0) { "odd-length hex string: $s" }
        return ByteArray(s.length / 2) { i ->
            val hi = Character.digit(s[2 * i], 16)
            val lo = Character.digit(s[2 * i + 1], 16)
            require(hi >= 0 && lo >= 0) { "non-hex character in $s" }
            ((hi shl 4) or lo).toByte()
        }
    }

    private fun padTo(data: ByteArray, length: Int): ByteArray {
        if (data.size >= length) return data
        val out = ByteArray(length)
        System.arraycopy(data, 0, out, 0, data.size)
        return out
    }

    private fun parseExpected(field: String): Map<String, Double> {
        if (field.isEmpty()) return emptyMap()
        val out = LinkedHashMap<String, Double>()
        for (pair in field.split(';')) {
            val eq = pair.indexOf('=')
            require(eq > 0) { "malformed expected pair: $pair" }
            val key = pair.substring(0, eq)
            val rawVal = pair.substring(eq + 1)
            if (rawVal.startsWith('"')) continue // value-table string; protocol emits raw scalar separately
            out[key] = rawVal.toDouble()
        }
        return out
    }

    private fun approxEqual(a: Double, b: Double): Boolean {
        if (a == b) return true
        val absA = Math.abs(a)
        val absB = Math.abs(b)
        val diff = Math.abs(a - b)
        if (a == 0.0 || b == 0.0) return diff < tolerance
        return diff / Math.max(absA, absB) < tolerance
    }
}
